  console.log(`Salary tx: ${txResult.status}${txResult.status === 201 ? ` id=${txResult.data.value.id}` : ""}`);
  console.log(`Voucher: ${vResult.status}${vResult.status === 201 ? ` id=${vResult.data.value.id} number=${vResult.data.value.number}` : ""}`);

