      employee: { id: empId }, date: "2026-08-20", year: 2026, month: 8,
      specifications: [
        { employee: { id: empId }, salaryType: { number: "1000" }, description: "Fastlønn aug 2026", year: 2026, month: 8, count: 1, rate: 15000, amount: 15000 },
